#!/usr/bin/env pwsh
$basedir=Split-Path $MyInvocation.MyCommand.Definition -Parent

$exe=""
$pathsep=":"
$env_node_path=$env:NODE_PATH
$new_node_path="A:\Qoovex\node_modules\.pnpm\next@15.5.15_@opentelemetry_b2aeeba3114d4027e3616508c6dc0066\node_modules\next\node_modules;A:\Qoovex\node_modules\.pnpm\next@15.5.15_@opentelemetry_b2aeeba3114d4027e3616508c6dc0066\node_modules;A:\Qoovex\node_modules\.pnpm\node_modules"
if ($PSVersionTable.PSVersion -lt "6.0" -or $IsWindows) {
  # Fix case when both the Windows and Linux builds of Node
  # are installed in the same directory
  $exe=".exe"
  $pathsep=";"
} else {
  $new_node_path="/proc/cygdrive/a/Qoovex/node_modules/.pnpm/next@15.5.15_@opentelemetry_b2aeeba3114d4027e3616508c6dc0066/node_modules/next/node_modules:/proc/cygdrive/a/Qoovex/node_modules/.pnpm/next@15.5.15_@opentelemetry_b2aeeba3114d4027e3616508c6dc0066/node_modules:/proc/cygdrive/a/Qoovex/node_modules/.pnpm/node_modules"
}
if ([string]::IsNullOrEmpty($env_node_path)) {
  $env:NODE_PATH=$new_node_path
} else {
  $env:NODE_PATH="$new_node_path$pathsep$env_node_path"
}

$ret=0
if (Test-Path "$basedir/node$exe") {
  # Support pipeline input
  if ($MyInvocation.ExpectingInput) {
    $input | & "$basedir/node$exe"  "$basedir/../next/dist/bin/next" $args
  } else {
    & "$basedir/node$exe"  "$basedir/../next/dist/bin/next" $args
  }
  $ret=$LASTEXITCODE
} else {
  # Support pipeline input
  if ($MyInvocation.ExpectingInput) {
    $input | & "node$exe"  "$basedir/../next/dist/bin/next" $args
  } else {
    & "node$exe"  "$basedir/../next/dist/bin/next" $args
  }
  $ret=$LASTEXITCODE
}
$env:NODE_PATH=$env_node_path
exit $ret
